document.addEventListener('DOMContentLoaded', function () {
  // Variáveis
  let selectedMethod = 'pix'; // Inicialmente Pix
  let cardNumberInput = document.getElementById('card-number');
  let cardExpiryInput = document.getElementById('card-expiry');
  let cardCvvInput = document.getElementById('card-cvv');
  let parcelasSelect = document.getElementById('parcelas');

  // Funções auxiliares
  function formatCurrency(amount) {
    return '$' + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  function applyDiscount(value) {
    return parseFloat(value) * 0.9; // 10% de desconto para Pix
  }

  function calculateInstallments(principal, interestRate) {
    const totalPayments = parseInt(parcelasSelect.value);
    if (totalPayments <= 3) {
      // Sem juros
      return { principal: principal, total: principal };
    }
    else if (totalPayments === 4) {
      // 5% juros sobre o valor inicial
      const interest = principal * 0.05;
      const monthlyInterest = (interest / totalPayments) * 12;
      return { principal: principal, total: principal + (monthlyInterest * totalPayments) };
    } else if (totalPayments === 5) {
      // 10% juros sobre o valor inicial
      const interest = principal * 0.10;
      const monthlyInterest = (interest / totalPayments) * 12;
      return { principal: principal, total: principal + (monthlyInterest * totalPayments) };
    }
  }

  // Evento: Informar dados
