    document.getElementById('value-input').value = 1000; // Adapte conforme necessidade
    document.getElementById('value-input').addEventListener('change', function () {
      const valor = parseFloat(this.target.value);
      document.getElementById('pix-value').textContent = formatCurrency(valor);
      document.getElementById('pix-total').textContent = formatCurrency(applyDiscount(valor));
    });
  }

  // Função para exibir painel Cartão de Crédito
  function showCreditCardPanel() {
    document.getElementById('credit-card-panel').style.display = 'block';
    document.getElementById('card-number').focus();
    // Captura eventos do campo número
    cardNumberInput.addEventListener('input', function () {
      const numero = this.value.replace(/\s/g, '');

      // Determina ícone baseada na primeira letra
      let bandeira = '';
      if (numero.startsWith('1234')) {
        bandeira = '<img src="https://via.placeholder.com/15" alt="Ícone 1234"/>';
      } else if (numero.startsWith('4321')) {
        bandeira = '<img src="https://via.placeholder.com/15" alt="Ícone 4321"/>';
      } else {
        bandeira = ''; // Mensagem de inválido será mostrada depois
      }

      // Mostra mensagem se não for 1234 nem 4321
      if (!numero.startsWith('1234') && !numero.startsWith('4321')) {
        alert('Número de cartão inválido!');
        return;
      }

      // Preenche campos
      cardNumberInput.value = numero;
      cardExpiryInput.value = 'MM/AAAA'; // Exemplo genérico
      cardCvvInput.value = '123'; // Exemplo genérico

      // Calcula parcelas
      const parcelas = parseInt(parcelasSelect.value);
      const principal = parseFloat(cardNumberInput.value);

      let juros = 0;
      if (parcelas === 4 || parcelas === 5) {
        juros = principal * 0.05; // 4 parcelas -> 5%
        // Para 5 parcelas, 10% -> já tratado acima
      }

      // Ajusta juros conforme número de parcelas
      if (parcelas >= 4) {
        juros = principal * 0.05; // 5% para 4 parcelas
      } else if (parcelas >= 5) {
        juros = principal * 0.10; // 10% para 5 parcelas
      }

      // Total das parcelas
      let totalAmortizacao = principal;
      let parcela = principal / parcelas;
      let juros_total = juros / parcelas;
      totalAmortizacao += parcela * (juros_total + juros_total); // Simplificação

      // Atualiza total abaixo do painel
      document.getElementById('total-amount').textContent = formatCurrency(totalAmortizacao);
    });
